css:
.fairenough-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2433;
    background: linear-gradient(170deg, #f3f5f9 0%, #eef1f7 50%, #e7ecf4 100%);
    border-radius: 18px;
}

.fairenough-container * {
    box-sizing: border-box;
}

.fairenough-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #16243f 0%, #243a63 55%, #355a8a 100%);
    color: #f2f5fb;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(22, 36, 63, 0.30);
}

.fairenough-header h1 {
    margin: 12px 0 12px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.fairenough-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0c45a;
    background: rgba(240, 196, 90, 0.12);
    border: 1px solid rgba(240, 196, 90, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.fairenough-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.58;
    color: #cdd8ec;
}

.fairenough-candidates {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.fairenough-cand {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(28, 36, 51, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.fairenough-cand-astrid { border-left: 5px solid #2f7d72; }
.fairenough-cand-henrik { border-left: 5px solid #b8852a; }

.fairenough-cand-name {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16243f;
}

.fairenough-cand-astrid .fairenough-cand-name { color: #2f7d72; }
.fairenough-cand-henrik .fairenough-cand-name { color: #a8761f; }

.fairenough-cand-meta {
    font-size: 0.82rem;
    color: #5b6678;
    line-height: 1.42;
}

.fairenough-cand-vs {
    align-self: center;
    font-size: 1.2rem;
    font-weight: 800;
    color: #355a8a;
    font-style: italic;
}

.fairenough-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #45506a;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.fairenough-period-counter #currentDay,
.fairenough-period-counter #maxPeriods {
    font-weight: 800;
    color: #355a8a;
}

.fairenough-round-name {
    background: rgba(53, 90, 138, 0.13);
    color: #2c4d7a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.fairenough-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8761f;
    background: rgba(184, 133, 42, 0.13);
    border: 1px solid rgba(184, 133, 42, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.fairenough-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.fairenough-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(28, 36, 51, 0.08);
    border-top: 4px solid #355a8a;
}

.fairenough-card-fairness { border-top-color: #355a8a; }
.fairenough-card-trust { border-top-color: #2f7d72; }
.fairenough-card-retention { border-top-color: #6a55b0; }
.fairenough-card-conflict { border-top-color: #b8852a; }

.fairenough-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7587;
}

.fairenough-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16243f;
    font-variant-numeric: tabular-nums;
}

.fairenough-card-fairness .fairenough-value { color: #355a8a; }
.fairenough-card-trust .fairenough-value { color: #2f7d72; }
.fairenough-card-retention .fairenough-value { color: #6a55b0; }
.fairenough-card-conflict .fairenough-value { color: #a8761f; }

.fairenough-sublabel {
    font-size: 0.76rem;
    color: #76829a;
    line-height: 1.36;
}

.fairenough-card-fairness.fairenough-fairness-danger { border-top-color: #cf4646; }
.fairenough-card-fairness.fairenough-fairness-danger .fairenough-value { color: #cf4646; }
.fairenough-card-fairness.fairenough-fairness-good { border-top-color: #2f7d72; }
.fairenough-card-fairness.fairenough-fairness-good .fairenough-value { color: #2f7d72; }

.fairenough-card-retention.fairenough-retention-danger { border-top-color: #cf4646; }
.fairenough-card-retention.fairenough-retention-danger .fairenough-value { color: #cf4646; }

.fairenough-clock-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde3ee;
    color: #45506a;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.fairenough-clock-bar #reputationDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #cf4646;
    font-weight: 800;
}

.fairenough-clock-bar.fairenough-rep-low #reputationDisplay { color: #2f7d72; }
.fairenough-clock-bar.fairenough-rep-mid #reputationDisplay { color: #a8761f; }

.fairenough-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #355a8a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 36, 51, 0.07);
}

.fairenough-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.fairenough-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #16243f;
    margin-bottom: 6px;
}

.fairenough-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #3b4759;
}

.fairenough-briefing-text strong { color: #2c4d7a; }
.fairenough-briefing-text em { color: #a8761f; font-style: italic; }

.fairenough-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 36, 51, 0.07);
}

.fairenough-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16243f;
    border-bottom: 2px solid #e6eaf2;
    padding-bottom: 8px;
}

.fairenough-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3749;
    margin: 14px 0 6px;
}

.fairenough-container select,
.fairenough-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c4cedd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1c2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.fairenough-container select:focus,
.fairenough-container input[type="number"]:focus {
    outline: none;
    border-color: #355a8a;
    box-shadow: 0 0 0 3px rgba(53, 90, 138, 0.16);
}

.fairenough-container select option {
    background-color: #ffffff;
    color: #1c2433;
}

.fairenough-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #355a8a;
}

.fairenough-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #45506a;
    margin-top: 4px;
}

.fairenough-range-readout span:nth-child(2) {
    color: #355a8a;
    font-weight: 800;
}

.fairenough-hint {
    font-size: 0.8rem;
    color: #76829a;
    margin-top: 6px;
    line-height: 1.42;
    font-style: italic;
}

.fairenough-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.fairenough-container .btn-primary {
    background: linear-gradient(135deg, #243a63 0%, #355a8a 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(36, 58, 99, 0.32);
}

.fairenough-container .btn-primary:hover {
    filter: brightness(1.08);
}

.fairenough-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c4cedd;
    color: #5b6678;
    background: transparent;
}

.fairenough-coach {
    background: linear-gradient(160deg, #16243f 0%, #1e2f50 100%);
    color: #e2e9f5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(22, 36, 63, 0.24);
}

.fairenough-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0c45a;
    margin-bottom: 8px;
}

.fairenough-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.fairenough-coach-body strong { color: #7fd3c4; }
.fairenough-coach-body em { color: #f0c45a; font-style: italic; }

.fairenough-history,
.fairenough-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 36, 51, 0.07);
}

.fairenough-history h3,
.fairenough-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16243f;
}

.fairenough-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3b4759;
}

.fairenough-container table#usfHistoryTable th {
    background: #eef2f8;
    color: #2c4d7a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6deea;
}

.fairenough-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f6;
    color: #3b4759;
}

.fairenough-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fc;
}

.fairenough-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .fairenough-container {
        padding: 14px;
    }
    .fairenough-header h1 {
        font-size: 1.75rem;
    }
    .fairenough-candidates {
        flex-direction: column;
    }
    .fairenough-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .fairenough-value {
        font-size: 2.05rem;
    }
    .fairenough-clock {
        margin-left: 0;
    }
    .fairenough-period-counter {
        font-size: 0.88rem;
    }
    .fairenough-clock-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .fairenough-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (fair- prefix; justice indigo theme) ---- */
.fair-completion { padding: 8px 4px 4px; }
.fair-cm-head { text-align: center; margin-bottom: 16px; }
.fair-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #4257b8; }
.fair-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #76829a; }
.fair-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #1e244f; }
.fair-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.fair-cm-yes { background: rgba(66,87,184,0.14); color: #4257b8; border: 1px solid rgba(66,87,184,0.45); }
.fair-cm-mid { background: rgba(118,130,154,0.15); color: #5f6b86; border: 1px solid rgba(118,130,154,0.42); }
.fair-cm-no  { background: rgba(200,64,52,0.12); color: #c84034; border: 1px solid rgba(200,64,52,0.42); }
.fair-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.fair-cm-metric { flex: 1 1 100px; min-width: 96px; background: rgba(66,87,184,0.07); border: 1px solid rgba(66,87,184,0.20); border-radius: 10px; padding: 10px 8px; text-align: center; }
.fair-cm-mv { display: block; font-size: 1.15rem; font-weight: 800; color: #4257b8; }
.fair-cm-ml { display: block; font-size: 0.66rem; margin-top: 4px; color: #76829a; text-transform: uppercase; letter-spacing: 0.03em; }
.fair-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #1e244f; }
.fair-cm-insights { margin: 0; padding-left: 20px; }
.fair-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #39415a; }

