(function() {
    'use strict';

    class FairEnoughAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Fair Enough`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Nordlys Forsikring AS · NOK).
            this.START_FAIRNESS = 58;     // perceived-fairness score now (/100), was 71
            this.FAIRNESS_FLOOR = 50;     // below this the grievance escalates to formal
            this.START_TRUST = 5.4;       // team trust (/10)
            this.START_CONFLICT = 42;     // grievance-resolution rating (/100)
            this.AT_RISK = 5;             // 3 younger + 2 senior experts at flight risk
            this.LOSS_COST = 750000;      // ~600k–900k kr replacement cost per person
            this.PROTECT_CAP = 350000;    // max retention/development spend (kr)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fairness: this.START_FAIRNESS,   // perceived-fairness score (/100)
                    trust: this.START_TRUST,         // team trust (/10)
                    conflict: this.START_CONFLICT,   // conflict-resolution rating (/100)
                    retained: this.AT_RISK,          // experts retained of the 5 at-risk
                    reputation: 70,                  // reputational-exposure index 0–100 (lower safer)
                    protectSpent: 0,                 // kr committed to retention/development
                    // Sticky run-defining penalty flags (set when an error is committed).
                    outcomeBeforeProcess: false,     // picked outcome without a real process
                    inconsistencyRun: false,         // criteria–choice inconsistency / silent re-weight
                    seniorityToAvoid: false,         // chose to placate a cohort, norm unspoken
                    visibilityBias: false,           // over-rewarded the visible win
                    platitudeRun: false,             // platitude / blunt rejection
                    ignoredReputation: false,        // ignored the public, reputational dimension
                    fairnessHistory: [this.START_FAIRNESS],
                    trustHistory: [this.START_TRUST],
                    conflictHistory: [this.START_CONFLICT],
                    retainHistory: [this.AT_RISK],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the COMMON ERRORS — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    diagnosis: `distributive`,
                    damaged: `dist_only`,
                    grievance: `park`,
                    listen: 30,
                    criteria: `tenure`,
                    voice: `head_only`,
                    bias: `none`,
                    speed: 40,
                    choice: `astrid`,
                    consistency: `reweight`,
                    norm: `seniority_silent`,
                    protect: 0,
                    announce: `outcome`,
                    rejection: `platitude`,
                    reputation: `ignore`,
                    plan: 40
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const di = document.getElementById(`diagnosisInput`);
                const da = document.getElementById(`damagedInput`);
                const gr = document.getElementById(`grievanceInput`);
                const li = document.getElementById(`listenInput`);
                if (di) decisions.diagnosis = di.value;
                if (da) decisions.damaged = da.value;
                if (gr) decisions.grievance = gr.value;
                if (li) decisions.listen = parseInt(li.value, 10);
                if (!Number.isFinite(decisions.listen) || decisions.listen < 0 || decisions.listen > 100) {
                    warn(`warn_listen_range`); return false;
                }
            } else if (round === 2) {
                const cr = document.getElementById(`criteriaInput`);
                const vo = document.getElementById(`voiceInput`);
                const bi = document.getElementById(`biasInput`);
                const sp = document.getElementById(`speedInput`);
                if (cr) decisions.criteria = cr.value;
                if (vo) decisions.voice = vo.value;
                if (bi) decisions.bias = bi.value;
                if (sp) decisions.speed = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.speed) || decisions.speed < 0 || decisions.speed > 100) {
                    warn(`warn_speed_range`); return false;
                }
            } else if (round === 3) {
                const ch = document.getElementById(`choiceInput`);
                const co = document.getElementById(`consistencyInput`);
                const no = document.getElementById(`normInput`);
                const pr = document.getElementById(`protectInput`);
                if (ch) decisions.choice = ch.value;
                if (co) decisions.consistency = co.value;
                if (no) decisions.norm = no.value;
                if (pr) decisions.protect = parseFloat(pr.value);
                if (!Number.isFinite(decisions.protect) || decisions.protect < 0) {
                    warn(`warn_protect_value`); return false;
                }
            } else if (round === 4) {
                const an = document.getElementById(`announceInput`);
                const re = document.getElementById(`rejectionInput`);
                const rp = document.getElementById(`reputationInput`);
                const pl = document.getElementById(`planInput`);
                if (an) decisions.announce = an.value;
                if (re) decisions.rejection = re.value;
                if (rp) decisions.reputation = rp.value;
                if (pl) decisions.plan = parseInt(pl.value, 10);
                if (!Number.isFinite(decisions.plan) || decisions.plan < 0 || decisions.plan > 100) {
                    warn(`warn_plan_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fairnessDelta = 0, trustDelta = 0, conflictDelta = 0, reputationDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the fairness failure. The score fell because the PROCESS was opaque.
                switch (d.diagnosis) {
                    case `procedural`: fairnessDelta += 3; conflictDelta += 6; reputationDelta -= 5; coachKey = `coach_r1_procedural`; break;
                    case `interactional`: fairnessDelta += 0.5; conflictDelta += 1; coachKey = `coach_r1_interactional`; break;
                    case `distributive`: fairnessDelta -= 2; conflictDelta -= 2; reputationDelta += 4; coachKey = `coach_r1_distributive`; break;
                    case `none`: fairnessDelta -= 4; conflictDelta -= 4; reputationDelta += 7; coachKey = `coach_r1_none`; break;
                }

                switch (d.damaged) {
                    case `proc_inter`: fairnessDelta += 2; conflictDelta += 4; break;
                    case `dist_only`: fairnessDelta -= 2; reputationDelta += 3; if (coachKey === `coach_default`) coachKey = `coach_r1_distonly`; break;
                    case `all_equal`: conflictDelta -= 1; break;
                }

                switch (d.grievance) {
                    case `acknowledge`: fairnessDelta += 3; trustDelta += 0.4; conflictDelta += 8; reputationDelta -= 6; break;
                    case `park`: conflictDelta -= 6; trustDelta -= 0.3; reputationDelta += 4; coachKey = `coach_r1_park`; break;
                    case `dismiss`: conflictDelta -= 12; trustDelta -= 0.8; reputationDelta += 9; coachKey = `coach_r1_dismiss`; break;
                }

                // Listening = the first procedural-justice signal (voice).
                if (d.listen >= 60) { trustDelta += 0.5; fairnessDelta += 2; reputationDelta -= 4; }
                else if (d.listen <= 25) { trustDelta -= 0.3; conflictDelta -= 3; }

                summaryKey = (d.diagnosis === `procedural` && d.damaged === `proc_inter` && d.grievance === `acknowledge`)
                    ? `sum_r1_good` : `sum_r1_weak`;
                if (d.diagnosis === `procedural` && d.damaged === `proc_inter` && d.grievance === `acknowledge` && d.listen >= 60) {
                    coachKey = `coach_r1_sharp`;
                }
            } else if (round === 2) {
                // Design the PROCESS (procedural justice) BEFORE choosing anyone.
                const depth = d.speed / 100;

                switch (d.criteria) {
                    case `balanced`: fairnessDelta += 7; trustDelta += 0.6; conflictDelta += 6; reputationDelta -= 6; break;
                    case `tenure`: fairnessDelta += 1; trustDelta -= 0.1; coachKey = `coach_r2_tenure`; break;
                    case `innovation`: fairnessDelta += 1; trustDelta -= 0.1; coachKey = `coach_r2_innovation`; break;
                    case `none`: fairnessDelta -= 8; trustDelta -= 0.6; conflictDelta -= 6; reputationDelta += 8; coachKey = `coach_r2_nocriteria`; break;
                }

                switch (d.voice) {
                    case `structured`: fairnessDelta += 6; trustDelta += 0.7; conflictDelta += 5; reputationDelta -= 5; break;
                    case `informal`: fairnessDelta -= 2; trustDelta -= 0.2; if (coachKey === `coach_default`) coachKey = `coach_r2_informal`; break;
                    case `head_only`: fairnessDelta -= 7; trustDelta -= 0.7; conflictDelta -= 5; reputationDelta += 7; coachKey = `coach_r2_headonly`; break;
                }

                switch (d.bias) {
                    case `checked`: fairnessDelta += 5; conflictDelta += 5; reputationDelta -= 5; break;
                    case `hr_light`: fairnessDelta += 1; break;
                    case `none`: fairnessDelta -= 5; conflictDelta -= 4; reputationDelta += 5; break;
                }

                // Process depth (vs. rushing the announcement). Procedural justice needs real depth.
                if (depth >= 0.6) { fairnessDelta += 4; trustDelta += 0.4; reputationDelta -= 4; }
                else if (depth <= 0.3) { fairnessDelta -= 4; conflictDelta -= 3; reputationDelta += 4; }

                // STICKY FLAG — Common Error #1: outcome before process. No real process at all.
                const noProcess = (d.criteria === `none` || d.voice === `head_only` || d.bias === `none`);
                if (noProcess && depth <= 0.4) {
                    ds.outcomeBeforeProcess = true;
                    coachKey = `coach_r2_outcomefirst`;
                }

                if (d.criteria === `balanced` && d.voice === `structured` && d.bias === `checked`) {
                    coachKey = `coach_r2_designed`;
                }

                summaryKey = (d.criteria === `balanced` && d.voice === `structured` && d.bias === `checked`) ? `sum_r2_good` :
                             (ds.outcomeBeforeProcess ? `sum_r2_noprocess` : `sum_r2_weak`);
            } else if (round === 3) {
                // Decide and allocate (distributive justice) + CONSISTENCY with Round 2.
                // The pick itself (Astrid/Henrik/third) is not punished — the JUSTICE of it is.

                switch (d.consistency) {
                    case `consistent`: fairnessDelta += 7; trustDelta += 0.7; conflictDelta += 6; reputationDelta -= 6; break;
                    case `override`: fairnessDelta -= 5; trustDelta -= 0.5; conflictDelta -= 4; reputationDelta += 5; coachKey = `coach_r3_override`; break;
                    case `reweight`:
                        // Common Error #2: criteria–choice inconsistency reads as rigged — worse than no criteria.
                        ds.inconsistencyRun = true;
                        fairnessDelta -= 10; trustDelta -= 1.0; conflictDelta -= 8; reputationDelta += 9; coachKey = `coach_r3_reweight`; break;
                }

                switch (d.norm) {
                    case `named`: fairnessDelta += 6; trustDelta += 0.6; conflictDelta += 5; reputationDelta -= 5; break;
                    case `seniority_silent`:
                        // Common Error #3: conflict avoidance via seniority, norm unspoken.
                        ds.seniorityToAvoid = true;
                        fairnessDelta -= 5; trustDelta -= 0.5; conflictDelta -= 4; reputationDelta += 5;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_seniority`; break;
                    case `visibility_silent`:
                        // Common Error #4: visibility bias, invisible mentoring under-valued.
                        ds.visibilityBias = true;
                        fairnessDelta -= 5; trustDelta -= 0.5; conflictDelta -= 4; reputationDelta += 5;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_visibility`; break;
                }

                // The third way is only rewarded when the process behind it was sound.
                if (d.choice === `thirdway` && d.consistency === `consistent` && d.norm === `named`) {
                    fairnessDelta += 3; conflictDelta += 3; coachKey = `coach_r3_thirdway`;
                }

                // Protect the disappointed cohort — derived retention support (kr).
                ds.protectSpent = Math.min(this.PROTECT_CAP, Math.round(ds.protectSpent + d.protect));
                if (d.protect >= this.PROTECT_CAP) { trustDelta += 0.4; conflictDelta += 4; }
                else if (d.protect <= 0) { conflictDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r3_noprotect`; }

                if (d.consistency === `consistent` && d.norm === `named` && d.protect >= this.PROTECT_CAP && !ds.outcomeBeforeProcess) {
                    coachKey = `coach_r3_just`;
                }

                summaryKey = (d.consistency === `consistent` && d.norm === `named`) ? `sum_r3_good` :
                             (ds.inconsistencyRun ? `sum_r3_inconsistent` :
                             (ds.seniorityToAvoid ? `sum_r3_seniority` :
                             (ds.visibilityBias ? `sum_r3_visibility` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Communicate & recover (interactional justice) + reputation.
                switch (d.announce) {
                    case `process`: fairnessDelta += 6; trustDelta += 0.6; conflictDelta += 5; reputationDelta -= 6; break;
                    case `outcome`: fairnessDelta -= 2; conflictDelta -= 2; reputationDelta += 3; coachKey = `coach_r4_outcome`; break;
                    case `silent`: fairnessDelta -= 6; trustDelta -= 0.6; conflictDelta -= 5; reputationDelta += 7; coachKey = `coach_r4_silent`; break;
                }

                switch (d.rejection) {
                    case `honest`: fairnessDelta += 6; trustDelta += 0.8; conflictDelta += 8; reputationDelta -= 5; break;
                    case `platitude`:
                        // Common Error #5: platitudes over honesty — an interactional-justice failure.
                        ds.platitudeRun = true;
                        fairnessDelta -= 6; trustDelta -= 0.8; conflictDelta -= 10; reputationDelta += 6; coachKey = `coach_r4_platitude`; break;
                    case `brief`:
                        ds.platitudeRun = true;
                        fairnessDelta -= 5; trustDelta -= 0.7; conflictDelta -= 8; reputationDelta += 5; coachKey = `coach_r4_brief`; break;
                }

                switch (d.reputation) {
                    case `address`: fairnessDelta += 4; reputationDelta -= 12; conflictDelta += 3; break;
                    case `ignore`: ds.ignoredReputation = true; reputationDelta += 7; coachKey = `coach_r4_ignore`; break;
                    case `suppress`: ds.ignoredReputation = true; fairnessDelta -= 4; trustDelta -= 0.5; reputationDelta += 10; coachKey = `coach_r4_suppress`; break;
                }

                // 60-day recovery plan firmness.
                if (d.plan >= 60) { fairnessDelta += 4; conflictDelta += 4; reputationDelta -= 4; }
                else if (d.plan <= 25) { fairnessDelta -= 3; conflictDelta -= 2; }

                if (d.announce === `process` && d.rejection === `honest` && d.reputation === `address` && d.plan >= 60) {
                    coachKey = `coach_r4_recover`;
                }

                summaryKey = (d.announce === `process` && d.rejection === `honest` && d.reputation === `address`) ? `sum_r4_good` :
                             (ds.platitudeRun ? `sum_r4_platitude` : `sum_r4_weak`);
            }

            // ---- Apply deltas (clamped). ----
            ds.fairness = Math.max(0, Math.min(100, Math.round((ds.fairness + fairnessDelta) * 10) / 10));
            ds.trust = Math.max(0, Math.min(10, Math.round((ds.trust + trustDelta) * 10) / 10));
            ds.conflict = Math.max(0, Math.min(100, Math.round(ds.conflict + conflictDelta)));
            ds.reputation = Math.max(0, Math.min(100, Math.round(ds.reputation + reputationDelta)));

            // ---- STICKY PENALTY CAPS — the headline anti-patterns must NOT reach the top
            // verdict even if later rounds are played well. Flags GATE & CAP, not soft deltas. ----
            // Outcome-before-process repeats the very opacity that filed the grievance.
            if (ds.outcomeBeforeProcess) {
                ds.fairness = Math.min(ds.fairness, this.FAIRNESS_FLOOR - 1);   // grievance went formal
                ds.conflict = Math.min(ds.conflict, 45);
            }
            // Inconsistency reads as a rigged process — worse than having no criteria.
            if (ds.inconsistencyRun) {
                ds.fairness = Math.min(ds.fairness, this.FAIRNESS_FLOOR - 2);
                ds.trust = Math.min(ds.trust, 4.5);
                ds.conflict = Math.min(ds.conflict, 40);
            }
            // Platitudes / blunt rejection cap the conflict-resolution rating.
            if (ds.platitudeRun) {
                ds.conflict = Math.min(ds.conflict, 48);
                ds.fairness = Math.min(ds.fairness, 62);
            }

            // ---- Retention is DERIVED: experts stay when fairness is high, trust holds,
            // the conflict is resolving, and the disappointed cohort is supported. ----
            const fairnessFactor = ds.fairness / 100;          // 0..1
            const trustFactor = ds.trust / 10;                 // 0..1
            const conflictFactor = ds.conflict / 100;          // 0..1
            const moneyFactor = 0.85 + 0.15 * (ds.protectSpent / this.PROTECT_CAP); // 0.85..1.0
            let keepShare = (0.42 * fairnessFactor + 0.30 * trustFactor + 0.28 * conflictFactor) * moneyFactor;
            // The disappointed counterparty leaves when a cohort was placated silently.
            if (ds.seniorityToAvoid || ds.visibilityBias) keepShare -= 0.18;
            keepShare = Math.max(0, Math.min(1, keepShare));
            ds.retained = Math.round(this.AT_RISK * keepShare);

            ds.fairnessHistory.push(ds.fairness);
            ds.trustHistory.push(ds.trust);
            ds.conflictHistory.push(ds.conflict);
            ds.retainHistory.push(ds.retained);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist composite score + grade to the reporting/grading layer every period.
            // (results_utils.php::express_resolveDomainScore -> performance.overallScore). Scoring UNCHANGED.
            const _score = this._composite(ds);
            ds.performance = { overallScore: _score, grade: this._gradeLetter(_score) };

            return {
                period: state.currentPeriod,
                fairness: ds.fairness,
                fairnessDelta: Math.round(fairnessDelta * 10) / 10,
                trust: ds.trust,
                trustDelta: Math.round(trustDelta * 10) / 10,
                conflict: ds.conflict,
                conflictDelta: Math.round(conflictDelta),
                retained: ds.retained,
                reputation: ds.reputation,
                protectSpent: ds.protectSpent,
                outcomeBeforeProcess: ds.outcomeBeforeProcess,
                inconsistencyRun: ds.inconsistencyRun,
                platitudeRun: ds.platitudeRun,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: _score,
                score: _score
            };
        }

        _repLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return t(`rep_high`);
            if (v >= 35) return t(`rep_mid`);
            return t(`rep_low`);
        }

        _fmtScore(v) {
            // Locale-aware one-decimal score: en "5.4", es "5,4".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`fairnessDisplay`, `domainState.fairness`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.fairenough-card-fairness`);
                if (card) {
                    card.classList.toggle(`fairenough-fairness-danger`, n < self.FAIRNESS_FLOOR);
                    card.classList.toggle(`fairenough-fairness-good`, n >= 70);
                }
                return `${Math.round(n)}`;
            });

            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => self._fmtScore(Number(v)));
            uiManager.bind(`conflictDisplay`, `domainState.conflict`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`retentionDisplay`, `domainState.retained`, (v) => {
                const r = Math.round(Number(v));
                const card = document.querySelector(`.fairenough-card-retention`);
                if (card) {
                    card.classList.toggle(`fairenough-retention-danger`, r < self.AT_RISK - 1);
                }
                return `${r} / ${self.AT_RISK}`;
            });

            uiManager.bind(`reputationDisplay`, `domainState.reputation`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.fairenough-clock-bar`);
                if (bar) {
                    bar.classList.toggle(`fairenough-rep-low`, n < 35);
                    bar.classList.toggle(`fairenough-rep-mid`, n >= 35 && n < 60);
                }
                return self._repLabel(n);
            });

            // Listen slider readout.
            const li = document.getElementById(`listenInput`);
            const liReadout = document.getElementById(`listenReadout`);
            if (li && liReadout) {
                liReadout.textContent = li.value;
                li.addEventListener(`input`, function() { liReadout.textContent = li.value; });
            }

            // Process-depth slider readout.
            const sp = document.getElementById(`speedInput`);
            const spReadout = document.getElementById(`speedReadout`);
            if (sp && spReadout) {
                spReadout.textContent = sp.value;
                sp.addEventListener(`input`, function() { spReadout.textContent = sp.value; });
            }
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, en) => (t ? t(k) : en);
            return {
                fairnessChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_fairness`, `Perceived fairness (/100)`),
                                data: [],
                                borderColor: `#355a8a`,
                                backgroundColor: `rgba(53,90,138,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#355a8a`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_conflict`, `Conflict resolution (/100)`),
                                data: [],
                                borderColor: `#b8852a`,
                                backgroundColor: `rgba(184,133,42,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b8852a`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_trust`, `Team trust (×10)`),
                                data: [],
                                borderColor: `#2f7d72`,
                                backgroundColor: `rgba(47,125,114,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f7d72`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#45506a`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#76829a` }, grid: { color: `rgba(28,36,51,0.06)` },
                                title: { display: true, text: L(`chart_axis_scale`, `0–100`), color: `#76829a` }
                            },
                            x: {
                                ticks: { color: `#76829a` }, grid: { color: `rgba(28,36,51,0.04)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#76829a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.fairnessHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Trust is /10 — scale ×10 to share the 0–100 axis.
            const trustScaled = ds.trustHistory.map((v) => Math.round(v * 10));
            return {
                fairnessChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.fairnessHistory.map((v) => Math.round(v)) },
                        { data: ds.conflictHistory },
                        { data: trustScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            const fairness = Math.round(ds.fairness);
            const trust = Math.round(ds.trust * 10) / 10;
            const conflict = Math.round(ds.conflict);
            const retained = Math.round(ds.retained);
            return Math.round(fairness * 0.34 + conflict * 0.24 + (trust * 10) * 0.22 + (retained / this.AT_RISK * 100) * 0.20);
        }

        _verdictKey(ds, composite) {
            const fairness = Math.round(ds.fairness);
            const trust = Math.round(ds.trust * 10) / 10;
            const conflict = Math.round(ds.conflict);
            const retained = Math.round(ds.retained);
            const fairlyDone = fairness >= 68;
            const trusted = trust >= 7;
            const conflictResolved = conflict >= 65;
            const retainedWell = retained >= this.AT_RISK - 1;
            const anyHeadlineError = ds.outcomeBeforeProcess || ds.inconsistencyRun || ds.platitudeRun ||
                                     ds.seniorityToAvoid || ds.visibilityBias || ds.ignoredReputation;
            if (fairlyDone && trusted && conflictResolved && retainedWell && !anyHeadlineError && composite >= 75) return `verdict_just`;
            if (ds.inconsistencyRun) return `verdict_rigged`;
            if (ds.outcomeBeforeProcess) return `verdict_outcomefirst`;
            if (ds.platitudeRun) return `verdict_platitude`;
            if ((ds.seniorityToAvoid || ds.visibilityBias) && !retainedWell) return `verdict_counterparty`;
            if (composite >= 58) return `verdict_defensible`;
            return `verdict_unfair`;
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 75) return `B`;
            if (c >= 62) return `C`;
            if (c >= 50) return `D`;
            if (c >= 35) return `E`;
            return `F`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fairness = Math.round(ds.fairness);
            const trust = Math.round(ds.trust * 10) / 10;
            const conflict = Math.round(ds.conflict);
            const retained = Math.round(ds.retained);

            const fairlyDone = fairness >= 68;
            const trusted = trust >= 7;
            const conflictResolved = conflict >= 65;
            const retainedWell = retained >= this.AT_RISK - 1;

            // v1.1.0: composite via shared helper so per-period persisted score == completion score.
            const composite = this._composite(ds);

            // Sticky run-defining patterns GATE the top verdict.
            const anyHeadlineError = ds.outcomeBeforeProcess || ds.inconsistencyRun || ds.platitudeRun ||
                                     ds.seniorityToAvoid || ds.visibilityBias || ds.ignoredReputation;

            let pattern = `mixed`;
            if (ds.inconsistencyRun) pattern = `rigged`;
            else if (ds.outcomeBeforeProcess) pattern = `outcomefirst`;
            else if (ds.platitudeRun) pattern = `platitude`;
            else if (ds.seniorityToAvoid) pattern = `seniority`;
            else if (ds.visibilityBias) pattern = `visibility`;
            else if (ds.ignoredReputation) pattern = `reputation`;
            else if (fairlyDone && conflictResolved && trusted) pattern = `just`;

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const verdictKey = this._verdictKey(ds, composite);
            const performance = T(verdictKey);

            const insights = [];
            if (pattern === `just`) insights.push(window.mySimulation.t(`insight_just`));
            else if (pattern === `rigged`) insights.push(window.mySimulation.t(`insight_rigged`));
            else if (pattern === `outcomefirst`) insights.push(window.mySimulation.t(`insight_outcomefirst`));
            else if (pattern === `platitude`) insights.push(window.mySimulation.t(`insight_platitude`));
            else if (pattern === `seniority`) insights.push(window.mySimulation.t(`insight_seniority`));
            else if (pattern === `visibility`) insights.push(window.mySimulation.t(`insight_visibility`));
            else if (pattern === `reputation`) insights.push(window.mySimulation.t(`insight_reputation`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (fairness < this.FAIRNESS_FLOOR) insights.push(window.mySimulation.t(`insight_formal`));
            if (!retainedWell) insights.push(window.mySimulation.t(`insight_retention`));
            if (ds.ignoredReputation && pattern !== `reputation`) insights.push(window.mySimulation.t(`insight_reputation`));
            if (fairlyDone && conflictResolved && !retainedWell) insights.push(window.mySimulation.t(`insight_counterparty`));

            return {
                fairness: fairness,
                trust: trust,
                conflict: conflict,
                retained: retained,
                fairlyDone: fairlyDone,
                trusted: trusted,
                conflictResolved: conflictResolved,
                retainedWell: retainedWell,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                verdictKey: verdictKey,
                grade: this._gradeLetter(composite),
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.grade || '';
            const verdict = s.performance || (s.verdictKey ? T(s.verdictKey) : '');
            const fairness = Math.round(Number(s.fairness || 0)) + '/100';
            const trust = this._fmtScore(Number(s.trust || 0)) + '/10';
            const conflict = Math.round(Number(s.conflict || 0)) + '/100';
            const retained = Math.round(Number(s.retained || 0)) + '/' + this.AT_RISK;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map((t) => '<li>' + t + '</li>').join('');
            const justWon = s.verdictKey === 'verdict_just';
            const badgeCls = justWon ? 'fair-cm-yes' : (score >= 62 ? 'fair-cm-mid' : 'fair-cm-no');
            const metric = (val, lab) => '<div class="fair-cm-metric"><span class="fair-cm-mv">' + val + '</span><span class="fair-cm-ml">' + lab + '</span></div>';
            const metrics = metric(fairness, T('cm_m_fairness'))
                + metric(trust, T('cm_m_trust'))
                + metric(conflict, T('cm_m_conflict'))
                + metric(retained, T('cm_m_retained'));
            return ''
                + '<div class="fair-completion">'
                +   '<div class="fair-cm-head">'
                +     '<div class="fair-cm-score">' + score + '<span class="fair-cm-score-max">/100</span></div>'
                +     '<div class="fair-cm-grade">' + verdict + ' <span class="fair-cm-badge ' + badgeCls + '">' + T('cm_grade') + ' ' + grade + '</span></div>'
                +   '</div>'
                +   '<div class="fair-cm-metrics">' + metrics + '</div>'
                +   '<div class="fair-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="fair-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.inconsistencyRun) return window.mySimulation.t(`hint_inconsistent`);
            if (ds.outcomeBeforeProcess) return window.mySimulation.t(`hint_outcomefirst`);
            if (ds.fairness < this.FAIRNESS_FLOOR) return window.mySimulation.t(`hint_formal`);
            if (ds.platitudeRun && state.currentPeriod >= 4) return window.mySimulation.t(`hint_platitude`);
            if (ds.reputation >= 65) return window.mySimulation.t(`hint_reputation`);
            if (ds.retained < this.AT_RISK - 1) return window.mySimulation.t(`hint_retention`);
            if (ds.fairness >= 70 && ds.conflict >= 65 && ds.trust >= 7) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.fairness`, label: `Fairness`, i18nKey: `col_fairness`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.trust`, label: `Trust`, i18nKey: `col_trust`, formatter: (v) => self._fmtScore(Number(v)) },
                { key: `results.conflict`, label: `Conflict`, i18nKey: `col_conflict`, formatter: (v) => `${Math.round(v)}` },
